using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEditor.SceneManagement;
namespace VRFPS.Tests {public class AuthoredWallTests {
[TestCase("Door wall left (1)")][TestCase("Door wall left (2)")]
public void AddedRoomWallBlocksBothDirections(string name){try{EditorSceneManager.OpenScene("Assets/VRFPS/Scenes/Maps/Room.unity");var map=Object.FindFirstObjectByType<MapRoot>();var visual=map.GetComponentsInChildren<Transform>().Single(t=>t.name=="ThemeGenerated").Find(name);Assert.That(visual,Is.Not.Null);var collision=map.collisionRoot.Find(name);Assert.That(collision,Is.Not.Null,"Missing authored wall collision");Physics.SyncTransforms();var mesh=visual.GetComponentInChildren<MeshFilter>();var b=mesh.sharedMesh.bounds;var center=mesh.transform.TransformPoint(b.center);var normal=mesh.transform.forward;int mask=1<<LayerMask.NameToLayer("WorldSolid");foreach(float sign in new[]{-1f,1f}){var ray=new Ray(center+normal*sign*.6f,-normal*sign);Assert.That(collision.GetComponentsInChildren<Collider>().Any(c=>c.enabled&&!c.isTrigger&&c.gameObject.layer==LayerMask.NameToLayer("WorldSolid")&&c.Raycast(ray,out var hit,1.2f)),Is.True,"Wall must block from either side");}}finally{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);}}
}}
